describe('Mobile Search Bar Expansion on Focus', () => {
  beforeEach(() => {
    cy.visit('/search');
  });

  it('should expand search bar on focus on mobile device', () => {
    // Verify initial state - search bar is collapsed
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').should('have.class', 'collapsed');

    // Intercept the focus event
    cy.intercept('POST', '/api/search').as('searchRequest');

    // Simulate mobile device by setting viewport
    cy.viewport('iphone-x');

    // Focus the search input
    cy.get('[data-testid="search-input"]').click();

    // Verify search bar expanded
    cy.get('[data-testid="search-input"]').should('have.class', 'expanded');

    // Verify search input is visible and editable
    cy.get('[data-testid="search-input"]').should('be.visible');
    cy.get('[data-testid="search-input"]').type('test search');

    // Verify search button is visible
    cy.get('[data-testid="search-button"]').should('be.visible');

    // Verify search button is enabled
    cy.get('[data-testid="search-button"]').should('not.be.disabled');

    // Verify API call is triggered
    cy.wait('@searchRequest');
  });

  it('should collapse search bar when focus is lost on mobile', () => {
    // Verify search bar is expanded
    cy.get('[data-testid="search-input"]').should('have.class', 'expanded');

    // Focus the search input
    cy.get('[data-testid="search-input"]').click();

    // Verify search input is focused
    cy.get('[data-testid="search-input"]').should('have.focus');

    // Verify search button is visible and enabled
    cy.get('[data-testid="search-button"]').should('be.visible');

    // Blur the search input
    cy.get('[data-testid="search-input"]').blur();

    // Verify search bar collapsed
    cy.get('[data-testid="search-input"]').should('have.class', 'collapsed');

    // Verify search button is still visible
    cy.get('[data-testid="search-button"]').should('be.visible');

    // Verify search button is disabled when input is not focused
    cy.get('[data-testid="search-button"]').should('be.disabled');
  });
});
